INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (20,20,'["Quelles méthodes utilisez-vous concrètement pour contrôler la qualité d''exécution sur un chantier de bâtiment en phase gros œuvre ?", "Comment procédez-vous pour détecter et gérer un écart entre les plans d''exécution et les travaux réalisés sur le terrain ?", "Quels outils ou logiciels avez-vous utilisés pour le suivi technique et administratif d''un chantier, et comment en avez-vous exploité les données ?", "Décrivez un projet sur lequel vous avez travaillé ces 4 dernières années où vous étiez directement responsable du contrôle ou du suivi des travaux.", "Avez-vous déjà géré une situation de retard de chantier ou de non-conformité avec un prestataire ? Comment l''avez-vous résolue ?", "Votre formation est en architecture et bâtiment, mais le poste de CGM exige des compétences en gestion de marché public — comment avez-vous comblé cet écart dans votre parcours ?", "Qu''est-ce qui vous a motivé à postuler à l''ADER plutôt qu''à un bureau d''études ou à un cabinet privé d''architecture ?", "Où vous voyez-vous dans 3 ans au sein d''une structure publique comme l''ADER, et quel rôle souhaitez-vous jouer dans le développement régional ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et des types de projets qu''elle pilote dans la région ?", "Quelle est, selon vous, la différence fondamentale entre travailler sur un chantier privé et gérer un marché public en termes de contraintes et de responsabilités ?"]','[0, 1, 3, 2, 5, 6, 7, 8, 9, 4]','{"0": "Bouchra OUCHENE", "1": "Fati RBIKI", "3": "Fati RBIKI", "2": "Fati RBIKI", "5": "Fati RBIKI", "6": "Fati RBIKI", "7": "Fati RBIKI", "8": "Fati RBIKI", "9": "Fati RBIKI", "4": "Fati RBIKI"}','2026-08-27 13:58:27.791081') ON CONFLICT (id) DO NOTHING;